if force == "mesh":
    # new code should use `load_mesh` for this
    log.debug(
        "`trimesh.load(force='mesh')` is a compatibility wrapper for `trimesh.load_mesh`"
    )
    return loaded.to_mesh()
elif force == "scene":
    # new code should use `load_scene` for this

if force == "mesh" and isinstance(loaded, Scene):
    return util.concatenate(loaded.dump())
if force == "scene" and not isinstance(loaded, Scene):
    return Scene(loaded)

return loaded
